Integer checks=0;
void check(bool okay,const StableId& why){++checks;if(!okay)throw std::runtime_error(why);}
template<class T>T must(Outcome<T> value,const StableId& why){check(value.ok,why+": "+value.error.original.code+" "+value.error.original.path);return std::move(value.value);}
void must(Status value,const StableId& why){check(value.ok,why+": "+value.error.original.code+" "+value.error.original.path);}
WorldMoment moment(Integer tick,const char* n="0",const char* d="1"){return {tick,must(normalize_fraction(n,d),"fraction")};}
// 身份只由本fixture的完整实际作者字节和显式模块选择派生。
CatalogIdentity identity(const BoundaryValue& source){using namespace boundary;CatalogIdentity id;id.content_id=get_string(source,"content_id","");id.content_version=get_string(source,"content_version","");id.content_digest=get_string(source,"content_digest","");id.schema_sha256=get_string(source,"schema_sha256","");id.ruleset_id="hanmo.native.local_society/1";id.artifact_sha256=picosha2::hash256_hex_string(must(render_boundary_json(source),"catalog render"));id.module_versions={{"dynamic_world","local_society_v1"},{"local_economy","1"},{"organization","2"},{"affairs","1"},{"director","2"},{"regional_life","1"}};auto selected=must(decode_exact_time_profile(boundary::field(boundary::field(boundary::field(source,"data","catalog"),"scenarios","data"),"engineering.exact_supply_reports","scenarios")),"explicit social profile");if(selected)must(append_exact_time_modules(id,&*selected),"exact explicit module selection");return id;}
// 检查副本只来自真实checkpoint，绝不以测试状态推进或补业务。
std::unique_ptr<WorldBundle> read(ResidentWorld& world,std::shared_ptr<const PreparedCatalog> catalog){auto bytes=must(world.checkpoint(),"checkpoint");auto seed=must(decode_world_checkpoint(bytes,*catalog),"decode checkpoint");auto view=std::make_unique<WorldBundle>(std::move(catalog),std::move(seed));must(view->validate(),"whole cold closure");return view;}
// 每次序号从原成功水位读取，Opening内部revision不能伪占玩家序号。
CommandEnvelope command(ResidentWorld& world,const WorldBundle& view,CommandPayload payload){auto now=must(world.identity(),"identity");CommandEnvelope e;e.world_id=now.world_id;e.execution_epoch=now.execution_epoch;e.expected_revision=now.revision;e.actor_id="actor.player";e.request_seq=*view.common.state().request_sequences.find(e.actor_id)+1;e.payload=std::make_shared<const CommandPayload>(std::move(payload));return e;}
void advance(ResidentWorld& world,std::shared_ptr<const PreparedCatalog> catalog,WorldMoment target){auto view=read(world,catalog);auto e=command(world,*view,{"advance",AdvanceCommand{target}});must(world.preview(e),"advance preview");must(world.submit(e),"advance submit");}
StableId service(ResidentWorld& world,std::shared_ptr<const PreparedCatalog> catalog){auto before=read(world,catalog);GrowthCommand p;p.kind="service";p.activity="rest";p.context=InteractionContext{"west.inn","actor.innkeeper","role.inn"};auto e=command(world,*before,{"service",p});must(world.preview(e),"rest preview");auto result=must(world.submit(e),"rest submit");auto replay=must(world.submit(e),"same original result replay");check(result->result_id==replay->result_id,"same accepted request once");auto after=read(world,catalog);check(after->common.wallet("wallet.player")->balance==before->common.wallet("wallet.player")->balance-20,"original fee once");check(after->common.wallet("wallet.inn")->balance==before->common.wallet("wallet.inn")->balance+20,"original provider credited once");check(after->growth.fixed_service_boundaries.size()==before->growth.fixed_service_boundaries.size()+1,"one real Started");return after->common.actor("actor.player")->action_id;}
BeginRun begin_request(ResidentWorld& world,const StableId& id,const StableId& action,Integer budget,bool saved=false){BeginRun r;r.expected=must(world.identity(),"run identity");r.run_id=id;r.actor_id="actor.player";r.action_id=action;r.max_half_days=budget;r.max_gross_outflow=100;r.resume_saved_scope=saved;return r;}
// 同一独立作者fixture移除显式新选择后，真实旧local_society仍走原checkpoint/1。
void legacy_checkpoint_regression(const BoundaryValue& input){auto legacy=input;auto* scenarios=legacy.find("data")->find("scenarios");auto* scenario=scenarios->find("engineering.exact_supply_reports");auto& fields=*scenario->as<BoundaryValue::Dict>();fields.erase(std::remove_if(fields.begin(),fields.end(),[](const auto& row){return row.first=="world_time"||row.first=="actor_foundation";}),fields.end());NativeInitRequest request;request.scenario_id="engineering.exact_supply_reports";request.world_seed="legacy-social-preserved";request.expected_catalog_identity=identity(legacy);auto init=must(make_native_initial_world(legacy,request),"legacy actual native initialization");check(!init.catalog->exact_time&&!init.catalog->actor_foundation,"legacy catalog has no exact selection");auto catalog=init.catalog;ResidentWorld world;must(world.install(catalog,std::move(init.seed),true),"legacy real install");auto bytes=must(world.checkpoint(),"legacy actual checkpoint remains available");auto selected=must(inspect_world_checkpoint_selection(bytes),"legacy checkpoint selector");(void)selected;auto seed=must(decode_world_checkpoint(bytes,*catalog),"legacy actual checkpoint decode");WorldBundle restored(catalog,std::move(seed));must(restored.validate(),"legacy cold world validate");check(restored.social.dynamic&&restored.social.dynamic->version==2&&!restored.social.dynamic->time2&&!restored.social_period_sources,"legacy physical Social remains 2 without new roots");check(must(encode_world_checkpoint(restored),"legacy unchanged checkpoint bytes")==bytes,"legacy roundtrip byte identity");}
